export function sortTasks(tasks: Task[], sort: TaskQuery['sort'], order: TaskQuery['order']): Task[] {
  const direction = order === 'asc' ? 1 : -1;
  return [...tasks].sort((a, b) => compareBy(a, b, sort) * direction);
}

function compareBy(a: Task, b: Task, sort: TaskQuery['sort']): number {
  switch (sort) {
    case 'priority':
      return priorityRank(a.priority) - priorityRank(b.priority);
    case 'dueDate':
      return compareNullableDate(a.dueDate, b.dueDate);
    case 'updatedAt':
      return a.updatedAt.localeCompare(b.updatedAt);
    case 'createdAt':
    default:
      return a.createdAt.localeCompare(b.createdAt);
  }
}

export function buildPage<T>(items: T[], total: number, page: number, pageSize: number): Page<T> {
  return {
    items,
    total,
    page,
    pageSize,
    pageCount: pageSize > 0 ? Math.ceil(total / pageSize) : 0,
  };
}

async list(query: TaskQuery): Promise<Page<Task>> {
  const all = [...this.tasks.values()];
  const filtered = applyFilters(all, query);
  const sorted = sortTasks(filtered, query.sort, query.order);
  const total = sorted.length;
  const start = (query.page - 1) * query.pageSize;
  const items = sorted.slice(start, start + query.pageSize);
  return buildPage(items, total, query.page, query.pageSize);
}
